parameters.jsCode:
const auth = $input.first().json.headers?.authorization || '';
if (!auth.startsWith('Bearer ')) return [{ json: { _error: 'AUTH_MISSING_TOKEN', _status: 401 } }];
const token = auth.slice(7);
try {
  const payload = JSON.parse(Buffer.from(token.split('.')[1], 'base64url').toString('utf8'));
  if (!payload.sub) throw new Error('No sub');
  if (payload.exp && Date.now()/1000 > payload.exp) throw new Error('JWT expired');
  if (!payload.tenant_id) throw new Error('No tenant_id');
  const role = payload.role || 'architect';
  if (!['architect','super_admin'].includes(role)) return [{ json: { _error: 'FORBIDDEN', _status: 403, _details: 'Solo architect/super_admin pueden aprobar o firmar' } }];
  const body = $input.first().json.body || {};
  const actId = (body.act_id || '').trim();
  const action = (body.action || '').trim();
  if (!actId) return [{ json: { _error: 'VALIDATION_FAILED', _status: 400, _details: 'act_id requerido' } }];
  if (!['approve','sign'].includes(action)) return [{ json: { _error: 'VALIDATION_FAILED', _status: 400, _details: "action debe ser 'approve' o 'sign'" } }];
  return [{ json: {
    user_id: payload.sub, tenant_id: payload.tenant_id, role,
    act_id: actId, action,
    request_id: 'req_' + Math.random().toString(36).slice(2, 10)
  }}];
} catch (e) {
  return [{ json: { _error: 'AUTH_INVALID_TOKEN', _status: 401, _details: e.message } }];
}

const r = $input.first()?.json;
const sess = $('Decode JWT + Body').first().json;
if (!r || !r.id) return [{ json: { _error: 'ACT_NOT_FOUND', _status: 404, _details: 'act_id no existe o sin acceso por RLS' } }];
const expectedFrom = sess.action === 'approve' ? 'draft' : 'approved';
if (r.prev_status !== expectedFrom) {
  return [{ json: { _error: 'INVALID_TRANSITION', _status: 409, _details: 'Para ' + sess.action + ' el acta debe estar en ' + expectedFrom + ' (actual: ' + r.prev_status + ')' } }];
}
return [{ json: {
  ...sess,
  act_id: r.id, project_id: r.project_id, project_name: r.project_name,
  visit_date: r.visit_date,
  prev_status: r.prev_status, new_status: r.new_status,
  approved_at: r.approved_at, signed_at: r.signed_at
}}];

